const baseSiteFetch = siteWorker.fetch.bind(siteWorker);
let authorContactCache = null;
let authorContactCacheUntil = 0;

function authorContactCsvRows(source) {
  const rows = []; let row = [], cell = '', quoted = false;
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    if (c === '"' && quoted && source[i + 1] === '"') { cell += '"'; i++; }
    else if (c === '"') quoted = !quoted;
    else if (c === ',' && !quoted) { row.push(cell); cell = ''; }
    else if ((c === '\n' || c === '\r') && !quoted) {
      if (c === '\r' && source[i + 1] === '\n') i++;
      row.push(cell); if (row.some(value => value.trim())) rows.push(row);
      row = []; cell = '';
    } else cell += c;
  }
  row.push(cell); if (row.some(value => value.trim())) rows.push(row);
  if (quoted || !rows.length) throw Error('invalid_catalog');
  const headers = rows.shift().map(value => value.trim().replace(/^\uFEFF/, '').toLowerCase());
  for (const required of ['id', 'deal', 'status']) if (!headers.includes(required)) throw Error('invalid_catalog');
  return rows.map(values => Object.fromEntries(headers.map((key, i) => [key, String(values[i] || '').trim()])));
}

async function authorContactRows() {
  if (authorContactCache && Date.now() < authorContactCacheUntil) return authorContactCache;
  const response = await fetch(authorContactSourceUrl, { redirect: 'follow', cache: 'no-store', signal: AbortSignal.timeout(15000) });
  if (!response.ok) throw Error('catalog_unavailable');
  const csv = await response.text();
  if (csv.length > 4_000_000) throw Error('catalog_oversized');
  const latest = new Map();
  for (const row of authorContactCsvRows(csv)) latest.set(row.id, row);
  authorContactCache = latest;
  authorContactCacheUntil = Date.now() + 60_000;
  return latest;
}

function authorContactDigits(value) {
  const phone = String(value || '').trim();
  if (!/^[+0-9 ().-]{7,40}$/.test(phone)) return '';
  let digits = phone.replace(/\D/g, '');
  if (digits.length === 10 && digits.startsWith('0')) digits = '996' + digits.slice(1);
  else if (digits.length === 9) digits = '996' + digits;
  if (!/^996\d{9}$/.test(digits)) return '';
  if (['996500804402', '996501804402', '996505804402'].includes(digits)) return '';
  return digits;
}

async function serveAuthorContact(request) {
  const url = new URL(request.url);
  const id = String(url.searchParams.get('author_contact') || '').trim();
  const headers = { 'cache-control': 'no-store', 'x-content-type-options': 'nosniff' };
  if (request.method !== 'GET') return Response.json({ ok: false, error: 'method_not_allowed' }, { status: 405, headers });
  if (!/^\d{1,20}$/.test(id) && !/^site-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)) {
    return Response.json({ ok: false, error: 'invalid_object' }, { status: 400, headers });
  }
  let record;
  try { record = (await authorContactRows()).get(id); }
  catch (_) { return Response.json({ ok: false, error: 'contact_service_unavailable' }, { status: 503, headers }); }
  const deal = String(record?.deal || '').toLowerCase();
  const status = String(record?.status || '').toLowerCase();
  if (!['аренда', 'продажа'].includes(deal) || status !== 'опубликован') {
    return Response.json({ ok: false, error: 'contact_unavailable' }, { status: 404, headers });
  }
  const raw = record.contact_privacy_mode === 'agent_private_v1'
    ? record.listing_agent_phone
    : record.public_contact_phone || record.phone || record.phone_number || record.contact_phone || record['телефон'];
  const digits = authorContactDigits(raw);
  if (!digits) return Response.json({ ok: false, error: 'contact_unavailable' }, { status: 404, headers });
  return Response.json({
    ok: true,
    phone: `+996 ${digits.slice(3, 6)} ${digits.slice(6, 9)} ${digits.slice(9)}`,
    tel: '+' + digits,
  }, { headers });
}

siteWorker.fetch = async function(request, env, context) {
  const url = new URL(request.url);
  if (url.pathname === '/' && url.searchParams.has('author_contact')) return serveAuthorContact(request);
  return baseSiteFetch(request, env, context);
};

