const seoOriginalObjectFetch = siteWorker.fetch.bind(siteWorker);
siteWorker.fetch = async function(request, env, ctx) {
  const url = new URL(request.url);
  if (url.pathname !== '/object.html' || request.method !== 'GET') return seoOriginalObjectFetch(request, env, ctx);
  const id = url.searchParams.get('id');
  if (!id) return seoOriginalObjectFetch(request, env, ctx);
  const response = await seoOriginalObjectFetch(request, env, ctx);
  if (!response.ok || !(response.headers.get('content-type') || '').includes('text/html')) return response;
  const canonicalUrl = 'https://liberterra.kg/object.html?id=' + encodeURIComponent(id);
  return new HTMLRewriter()
    .on('link#objectCanonical', { element(el) { el.setAttribute('href', canonicalUrl); } })
    .on('meta[property="og:url"]', { element(el) { el.setAttribute('content', canonicalUrl); } })
    .transform(response);
};

